const item = $input.first();
const kind = item.json.query?.kind;
const fail = (status, error) => [{ json: { valid: false, status, error } }];
if (kind !== 'cv' && kind !== 'cover_letter') return fail(400, 'bad_kind');
if (!item.binary?.file) return fail(400, 'bad_file');
const bytes = await this.helpers.getBinaryDataBuffer(0, 'file');
if (bytes.length === 0) return fail(400, 'bad_file');
if (bytes.length > 5 * 1024 * 1024) return fail(413, 'file_too_large');
return [{ json: { valid: true, kind }, binary: { file: item.binary.file } }];

// Validates the query before the database or the worker is touched. Anything else is a 400.
const q = $json.query || {};
if (q.kind !== 'cv' && q.kind !== 'cover_letter') return { json: { ok: false, code: 400, body: { error: 'bad_request' } } };
return { json: { ok: true, kind: q.kind } };

const r = $json;
if (r.error) return { json: { code: 500, body: { error: 'server_error' } } };
if (!r.doc) return { json: { code: 404, body: { error: 'no_document' } } };
return { json: { code: 200, body: r.doc } };

// Validates the save request before the database or the worker is touched. The facts themselves are
// checked by the worker (shape, limits); here only the envelope.
const b = $json.body;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const fail = (code, error) => ({ json: { ok: false, code, body: { error } } });
const isObj = (x) => typeof x === 'object' && x !== null && !Array.isArray(x);
if (!isObj(b)) return fail(400, 'bad_request');
// 200 KB of UTF-8, measured on the parsed body (the worker enforces the same limit).
const text = JSON.stringify(b);
let bytes = 0;
for (let i = 0; i < text.length; i++) {
  const c = text.charCodeAt(i);
  if (c < 0x80) bytes += 1;
  else if (c < 0x800) bytes += 2;
  else if (c >= 0xd800 && c <= 0xdbff) { bytes += 4; i++; }
  else bytes += 3;
}
if (bytes > 200 * 1024) return fail(413, 'too_large');
if (b.kind !== 'cv' && b.kind !== 'cover_letter') return fail(400, 'bad_request');
if (typeof b.id !== 'string' || !UUID.test(b.id)) return fail(400, 'bad_request');
// The version the edit was made on: the file's content hash from the facts answer.
if (typeof b.contentHash !== 'string' || !/^[0-9a-f]{64}$/.test(b.contentHash)) return fail(400, 'bad_request');
if (!Object.prototype.hasOwnProperty.call(b, 'facts') || b.facts === undefined) return fail(400, 'bad_request');
return { json: { ok: true, kind: b.kind, id: b.id.toLowerCase(), contentHash: b.contentHash, undo: b.facts === null, facts: b.facts } };

// An edit goes to /documents/facts/check with the file's facts as base (answers sameAsBase).
// Undo never runs the strict validator: /documents/checks recomputes the warnings of the file's facts.
const r = $json;
const req = $('Check save request').first().json;
const fail = (code, error) => ({ json: { ok: false, code, body: { error } } });
if (r.error) return fail(500, 'server_error');
if (!r.doc) return fail(409, 'document_changed');
if (req.undo) return { json: { ok: true, path: '/documents/checks', body: { kind: req.kind, facts: r.doc.structured } } };
return { json: { ok: true, path: '/documents/facts/check', body: { kind: req.kind, facts: req.facts, base: r.doc.structured } } };

// The worker's answer. Bad facts are a 400 naming the first bad value; any other failure is a 500.
const res = $json;
const b = res.body;
const req = $('Check save request').first().json;
const fail = (code, body) => ({ json: { ok: false, code, body } });
if (res.statusCode === 400 && b && b.error === 'invalid_facts') {
  // A path with odd characters (an extra key such as "a b") is still the user's bad facts: name the whole value.
  const ok = typeof b.path === 'string' && /^facts([.[]|$)/.test(b.path) && /^[A-Za-z0-9_.\[\]]{1,200}$/.test(b.path);
  return fail(400, { error: 'invalid_facts', path: ok ? b.path : 'facts' });
}
if (res.statusCode === 413) return fail(413, { error: 'too_large' });
const isObj = (x) => typeof x === 'object' && x !== null && !Array.isArray(x);
if (res.statusCode !== 200 || !b || !Array.isArray(b.warnings)) return fail(500, { error: 'server_error' });
// Undo, or facts that say the same as the file's (both cleaned the same way): no edit is stored.
if (req.undo) return { json: { ok: true, facts: null, warnings: JSON.stringify(b.warnings) } };
if (!isObj(b.facts) || typeof b.sameAsBase !== 'boolean') return fail(500, { error: 'server_error' });
return { json: { ok: true, facts: b.sameAsBase ? null : JSON.stringify(b.facts), warnings: JSON.stringify(b.warnings) } };

const r = $json;
if (r.error) return { json: { code: 500, body: { error: 'server_error' } } };
if (!r.doc) return { json: { code: 409, body: { error: 'document_changed' } } };
return { json: { code: 200, body: r.doc } };

// Validates the query before the database or the worker is touched. Anything else is a 400.
const q = $json.query || {};
if (q.kind !== 'cv' && q.kind !== 'cover_letter') return { json: { ok: false, code: 400, body: { error: 'bad_request' } } };
return { json: { ok: true, kind: q.kind } };

// The response headers for the stored file. The bytes are passed on untouched.
const item = $input.first();
const res = item.json;
const fail = (code, error) => [{ json: { ok: false, code, body: { error } } }];
if (res.statusCode === 404) return fail(404, 'no_document');
if (res.statusCode !== 200 || !item.binary || !item.binary.data) return fail(502, 'file_unavailable');
const headers = res.headers || {};
const PDF = 'application/pdf';
const DOCX = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
const type = String(headers['content-type'] || '').split(';')[0].trim().toLowerCase();
if (type !== PDF && type !== DOCX) return fail(502, 'file_unavailable');
const ref = typeof headers['x-source-ref'] === 'string' ? headers['x-source-ref'] : '';
// The worker stores only safe names; keep the plain name to the same characters anyway.
let plain = ref.replace(/[^A-Za-z0-9 ._()-]/g, '').replace(/^[ .]+/, '');
const ext = type === PDF ? '.pdf' : '.docx';
if (!plain.toLowerCase().endsWith(ext)) plain = 'Document' + ext;
const name = ref || plain;
const encoded = encodeURIComponent(name).replace(/['()*]/g, (c) => '%' + c.charCodeAt(0).toString(16).toUpperCase());
return [{
  json: {
    ok: true,
    contentType: type,
    disposition: `${type === PDF ? 'inline' : 'attachment'}; filename="${plain}"; filename*=UTF-8''${encoded}`,
  },
  binary: item.binary,
}];
